function linkNodes(){const positions=new Map(),used=new Set();for(const o of items){if(o.kind!=='line')continue;for(const key of ['a','b']){const p=o[key],pos=p.x.toFixed(6)+','+p.y.toFixed(6);let node=positions.get(pos);if(!node){let id=typeof p.nodeId==='string'&&!used.has(p.nodeId)?p.nodeId:uid();used.add(id);node={x:p.x,y:p.y,nodeId:id};positions.set(pos,node)}o[key]={...node}}}}
