function hit(p,linesOnly=false){for(let i=items.length-1;i>=0;i--){let o=items[i];if(o.kind==='text'&&mode!=='select'&&mode!=='text')continue;if(mode==='text'&&o.kind!=='text')continue;if(linesOnly&&o.kind!=='line')continue;if(o.kind==='line'){let dx=o.b.x-o.a.x,dy=o.b.y-o.a.y,t=Math.max(0,Math.min(1,((p.x-o.a.x)*dx+(p.y-o.a.y)*dy)/(dx*dx+dy*dy||1)));if(distance(p,{x:o.a.x+t*dx,y:o.a.y+t*dy})<10/view.s)return o}else{let q=local(o,p);if(Math.abs(q.x)<o.w/2+8/view.s&&Math.abs(q.y)<o.h/2+8/view.s)return o}}return null}
