function syncTextEditor(){const o=items.find(o=>o.id===selection),box=$('#textEditor');if(canvasLocked||!o||o.kind!=='text'||!['select','text'].includes(mode)){box.hidden=true;textEditId=null;textSession=false;return}box.hidden=false;const p=screen(o),input=$('#textInput');if(textEditId!==o.id){textEditId=o.id;input.value=o.text;textSession=false}Object.assign(box.style,{left:p.x+'px',top:p.y+'px',width:o.w*view.s+'px',height:o.h*view.s+'px',transform:'translate(-50%,-50%) rotate('+o.angle+'deg)'});Object.assign(input.style,{fontFamily:o.font,fontSize:o.fontSize*view.s+'px',lineHeight:1.25,padding:4*view.s+'px',color:o.color})}
function inspectText(o){const el=$('#inspector');el.innerHTML='<h3>Texto</h3><label>Fuente<select id="textFont">'+textFonts.map(f=>'<option>'+f+'</option>').join('')+'</select></label><div class="row"><label>Tamaño<input id="textSize" type="number" min="1" max="300" step="1"></label><label>Color del texto<input id="textColor" type="color"></label></div><div class="row"><label>Borde<select id="textBorder"><option value="none">Sin borde</option><option value="solid">Continuo</option><option value="dotted">Punteado</option><option value="dashed">Rayado</option></select></label><label>Color del borde<input id="textBorderColor" type="color"></label></div><div class="row" style="margin-top:12px"><button id="delete" class="danger">Eliminar</button><button id="done">Listo</button></div>';for(const [id,key] of [['textFont','font'],['textSize','fontSize'],['textColor','color'],['textBorder','border'],['textBorderColor','borderColor']]){const input=$('#'+id);input.value=o[key];input.onchange=()=>{if(canvasLocked)return;const v=key==='fontSize'?Number(input.value):input.value;if(key==='fontSize'&&(!Number.isFinite(v)||v<1||v>300)){inspect();return}checkpoint();o[key]=v;if(key==='fontSize')o.autoFont=false;measureTextBox(o);commit();inspect()}}$('#delete').onclick=remove;$('#done').onclick=()=>{selection=null;inspect();render()}}
const imgs={};Object.keys(shapes).forEach(k=>{let im=new Image();im.onload=()=>{const cv=document.createElement('canvas');cv.width=300;cv.height=220;const g=cv.getContext('2d');g.drawImage(im,0,0,300,220);const data=g.getImageData(0,0,300,220).data;let left=300,top=220,right=0,bottom=0;for(let y=0;y<220;y++)for(let x=0;x<300;x++)if(data[(y*300+x)*4+3]>0){left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y)}im.crop=right>=left?[left/5,top/5,(right-left+1)/5,(bottom-top+1)/5]:[0,0,60,44];render()};im.src='data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="60" height="44" viewBox="0 0 60 44" preserveAspectRatio="none" stroke="#718366" fill="#e7ecdf" stroke-width="1.3">'+shapes[k]+'</svg>');imgs[k]=im});
