$('#export').onchange=async e=>{let format=e.target.value;e.target.value='';if(!format)return;let name=$('#name').value||'plano';if(format==='json'){download(JSON.stringify({version:1,name,items},null,2),name+'.json','application/json');toast('Proyecto JSON guardado en Descargas');return}try{await Promise.all(Object.values(imgs).map(im=>im.decode()));let output=exportCanvas();if(format==='png'){output.toBlob(blob=>download(blob,name+'.png','image/png'))}else download(makePDF(output),name+'.pdf','application/pdf');toast('Plano completo exportado')}catch(err){toast('No se pudo exportar el plano. Inténtalo de nuevo.')}};
