function changeGrid(factor){if(canvasLocked)return;const next=Math.max(.1,Math.min(10000,Number((step()*factor).toFixed(6))));$('#auto').checked=false;$('#step').value=next;render();toast('Separación del grid: '+num(next)+' cm')}
$('#gridLess').onclick=()=>changeGrid(10);$('#gridMore').onclick=()=>changeGrid(.1);
function updateAngleTools(){angleSelection=angleSelection.filter(id=>items.some(o=>o.id===id&&o.kind==='line'));$('#angleOpen').textContent='Establecer ángulos ('+angleSelection.length+')';$('#angleOpen').disabled=angleSelection.length<2}
function sharedJobs(){linkNodes();const lines=angleSelection.map(id=>items.find(o=>o.id===id)).filter(Boolean),jobs=[];for(let j=1;j<lines.length;j++)for(let i=0;i<j;i++)for(const k of ['a','b']){const pivot=lines[i][k];for(const t of ['a','b'])if(pivot.nodeId===lines[j][t].nodeId)jobs.push({first:lines[i].id,second:lines[j].id,pivot:pivot.nodeId,i:i+1,j:j+1})}return jobs}
function jobGeometry(job){const a=items.find(o=>o.id===job.first),b=items.find(o=>o.id===job.second);if(!a||!b)return null;const p=[a.a,a.b].find(p=>p.nodeId===job.pivot),u=[a.a,a.b].find(p=>p.nodeId!==job.pivot),v=[b.a,b.b].find(p=>p.nodeId!==job.pivot);return p&&u&&v?{p,u,v}:null}
