function applyAngles(jobs,values){if(canvasLocked)return false;if(values.some(v=>!Number.isFinite(v)||v<0||v>180))return false;checkpoint();const locked=new Set();angleErrors=[];let conflicts=0;for(let i=0;i<jobs.length;i++){const g=jobGeometry(jobs[i]);if(!g)continue;const {p,u,v}=g,len=distance(p,v);locked.add(p.nodeId);locked.add(u.nodeId);if(len<1e-8||distance(p,u)<1e-8){angleErrors.push(p.nodeId);conflicts++;continue}const base=Math.atan2(u.y-p.y,u.x-p.x),r=values[i]*Math.PI/180;const choices=[base+r,base-r].map(a=>({x:p.x+len*Math.cos(a),y:p.y+len*Math.sin(a)}));choices.sort((a,b)=>distance(a,v)-distance(b,v));const next=choices[0];if(distance(next,v)>1e-6&&locked.has(v.nodeId)){angleErrors.push(v.nodeId);conflicts++;continue}moveNode(v,next);locked.add(v.nodeId)}commit();$('#angleStatus').textContent=conflicts?'No se puede establecer el ángulo: es necesario mover un nodo ya fijado. ('+conflicts+' conflicto'+(conflicts===1?'':'s')+')':'';if(!conflicts)toast('Ángulos establecidos');return true}
let individualAngles=false,individualValues=[],commonAngle='90';
function angleValue(value){return String(value).trim()===''?NaN:Number(String(value).replace(',','.'))}
function renderAngleFields(){const el=$('#angleFields');el.innerHTML=individualAngles?angleJobs.map((j,i)=>'<label class="angle-entry"><span>Nodo '+(i+1)+' · líneas '+j.i+' y '+j.j+'</span><input class="angle-value" aria-label="Ángulo entre líneas '+j.i+' y '+j.j+'" type="text" inputmode="decimal">°</label>').join(''):'<label class="angle-entry"><span>Ángulo para todos</span><input id="commonAngle" aria-label="Ángulo para todos los nodos" type="text" inputmode="decimal">°</label>';if(individualAngles)document.querySelectorAll('.angle-value').forEach((e,i)=>e.value=individualValues[i]);else $('#commonAngle').value=commonAngle;$('#angleToggle').textContent=individualAngles?'Usar un ángulo para todos':'Modificar cada ángulo';}
$('#angleOpen').onclick=()=>{angleJobs=sharedJobs();if(!angleJobs.length){toast('Selecciona líneas con extremos conectados');return}individualAngles=false;individualValues=angleJobs.map(j=>{const g=jobGeometry(j);return g?Number(interior(g).toFixed(4)):0});commonAngle='90';renderAngleFields();$('#angleDialog').showModal()};
$('#angleToggle').onclick=()=>{if(individualAngles)individualValues=[...document.querySelectorAll('.angle-value')].map(e=>e.value);else commonAngle=$('#commonAngle').value;individualAngles=!individualAngles;renderAngleFields()};
$('#angleCancel').onclick=()=>$('#angleDialog').close();$('#angleApply').onclick=()=>{const values=individualAngles?[...document.querySelectorAll('.angle-value')].map(e=>angleValue(e.value)):angleJobs.map(()=>angleValue($('#commonAngle').value));if(!applyAngles(angleJobs,values)){toast('Introduce ángulos entre 0 y 180 grados');return}$('#angleDialog').close()};$('#angleClear').onclick=()=>{angleSelection=[];angleErrors=[];$('#angleStatus').textContent='';updateAngleTools();render()};

