$('#textInput').oninput=e=>{const o=items.find(o=>o.id===textEditId);if(canvasLocked||!o)return;if(!textSession){checkpoint();textSession=true}o.text=e.target.value.slice(0,10000);measureTextBox(o);commit()};$('#textInput').onblur=()=>{textSession=false};
