let holdTimer=null,holdStart=null,holdTarget=null;
function cancelHold(){clearTimeout(holdTimer);holdTimer=null;holdStart=null;holdTarget=null}
function showProperties(id){if(canvasLocked)return;const o=items.find(o=>o.id===id);if(!o||!['select','text'].includes(mode)||(mode==='text'&&o.kind!=='text'))return;if(action?.before)items=JSON.parse(action.before);action=null;selection=id;propertiesId=id;inspect();render()}
function startHold(e,id){cancelHold();if(canvasLocked||!id)return;holdStart={x:e.clientX,y:e.clientY};holdTarget=id;holdTimer=setTimeout(()=>{const target=holdTarget;cancelHold();showProperties(target)},550)}
const textPointerDown=c.onpointerdown,textPointerMove=c.onpointermove,textPointerUp=c.onpointerup,textPointerCancel=c.onpointercancel;
c.onpointerdown=e=>{if(e.button===2)return;if(!canvasLocked){propertiesId=null;inspect()}textPointerDown(e);if(pointers.size>1){cancelHold();return}if(['select','text'].includes(mode))startHold(e,selection)};
c.onpointermove=e=>{if(holdStart&&distance(holdStart,{x:e.clientX,y:e.clientY})>8)cancelHold();textPointerMove(e)};
c.onpointerup=e=>{cancelHold();textPointerUp(e)};c.onpointercancel=e=>{cancelHold();textPointerCancel(e)};
c.oncontextmenu=e=>{e.preventDefault();if(canvasLocked)return;const o=hit(world(pos(e)));if(o)showProperties(o.id)};
$('#textInput').oncontextmenu=e=>{e.preventDefault();showProperties(textEditId)};
$('#textInput').onpointerdown=e=>startHold(e,textEditId);$('#textInput').onpointermove=e=>{if(holdStart&&distance(holdStart,{x:e.clientX,y:e.clientY})>8)cancelHold()};$('#textInput').onpointerup=cancelHold;$('#textInput').onpointercancel=cancelHold;
